mapper.update:
update pt_log
   set countchange = #{countChange}
 where salesid = #{salesId}
   and status = '충전'

mapper.select:
select ifnull(sum(countchange), 0)
from pt_log
where memnum = #{memNum}

select usageid, memnum, empnum, status, countchange, createdat, salesid, regid
from pt_log
where usageid = #{refundId}

mapper.insert:
insert into pt_log (
    memnum, empnum, status, countchange, createdat, salesid, regid
)
select
    #{memNum}, #{empNum}, '소비', -1, now(), null, #{regId, jdbcType=NULL}
where (
    select ifnull(sum(countchange), 0)
    from pt_log
    where memnum = #{memNum}
) > 0

mapper.select:
select ifnull(sum(
    case
        when status = '소비' then 1                 
        when status = '예약취소' then -1           
        when status = '부분환불' then abs(countchange)   
        when status = '전체환불' then abs(countchange) 
        else 0
    end
), 0) as usedcount
from pt_log
where memnum = #{memNum}
  and (
       salesid = #{salesId}                
    or (
          usageid > (
              select min(usageid)
              from pt_log
              where memnum = #{memNum}
                and salesid = #{salesId}
                and status = '충전'
          )
       )
  )

select p.usageid as usageId, p.memnum as memNum, m.memname as memberName, p.empnum as empNum, e.empname as empName, p.status as status, p.countchange as countChange, date_format(p.createdat, '%Y-%m-%d %H:%i:%s') as createdAt from pt_log p left join member m on p.memnum = m.memnum left join employee e on p.empnum = e.empnum where 1=1
and p.createdat >= str_to_date(#{startDate}, '%Y-%m-%d')
and p.createdat < date_add(str_to_date(#{endDate}, '%Y-%m-%d'), interval 1 day)
and p.memnum = #{memNum}
and p.empnum = #{empNum}
order by p.usageid desc limit #{limit} offset #{offset}

select count(*) from pt_log p where 1=1
and p.createdat >= str_to_date(#{startDate}, '%Y-%m-%d')
and p.createdat < date_add(str_to_date(#{endDate}, '%Y-%m-%d'), interval 1 day)
and p.memnum = #{memNum}
and p.empnum = #{empNum}
